names_rd=fieldnames(EGB_rd2);
for i=1:length(names_rd)-3
    EGB_rd2.(names_rd{i})(EGB_rd2.(names_rd{i})>999)=NaN;
end
EGB_rd2.Properties.DimensionNames{1}='Time';
EGB_rd2=retime(EGB_rd2,'daily',@nanmedian);
