plotFigControl(EGB_rd2,EGB_st.name); %[output:87ca5969] %[output:4eecf339] %[output:9eafa6ec] %[output:30ba0335] %[output:0397571c] %[output:164f8c31] %[output:936a6d92] %[output:7714415b]
